/** Application-owned text: never generated by the provider. */
export function reflectiveOutlook(topic = '', context = '', care = false): string {
  if (care) return 'Ứng dụng không đưa dự đoán kết quả. Bạn có thể liên hệ người thân hoặc chuyên gia để được lắng nghe và hỗ trợ ngay lúc này.';
  const text = `${topic} ${context}`.normalize('NFD').replace(/\p{M}/gu, '').replace(/đ/g, 'd').toLowerCase();
  if (/suc khoe|thuoc|dieu tri|benh|kham|phau thuat/.test(text)) return 'Ứng dụng không đưa dự đoán kết quả về sức khỏe. Bạn có thể ghi lại điều đang băn khoăn để trao đổi với chuyên gia y tế.';
  if (/tai chinh|dau tu|tien|chung khoan|khoan vay/.test(text)) return 'Ứng dụng không đưa dự đoán kết quả về tài chính. Bạn có thể chuẩn bị những câu hỏi cần làm rõ cùng chuyên gia phù hợp.';
  return 'Ứng dụng không đưa dự đoán kết quả cho chủ đề này. Bạn có thể ghi lại điều cần làm rõ và chuẩn bị câu hỏi cho chuyên gia phù hợp.';
}
